// A RPC devolve um array; dependendo da versão o n8n entrega tudo num item só.
// Normaliza para 1 item por criativo e calcula o nome do arquivo no Storage.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const lista = Array.isArray(j) ? j : (Array.isArray(j.data) ? j.data : [j]);
  for (const r of lista) {
    if (!r || !r.ad_name || !r.drive_file_id) continue;
    // Storage não aceita acento nem espaço.
    const slug = String(r.ad_name)
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    out.push({ json: { ad_name: r.ad_name, tipo: r.tipo, drive_file_id: r.drive_file_id, slug } });
  }
}
return out;

// Decide extensão e destino pelo mimeType REAL do arquivo baixado — não pelo
// nome do criativo. Um "_vid_" pode ter sido exportado como gif/imagem, e o
// que vale para o <video> do popup é o tipo de verdade.
const ctx = $('Normalizar').item.json;
const bin = $input.item.binary?.data ?? {};
const mime = bin.mimeType || 'application/octet-stream';
const ehVideo = mime.startsWith('video/');
const ext = ehVideo
  ? (mime.includes('quicktime') ? 'mov' : 'mp4')
  : (mime.includes('png') ? 'png' : (mime.includes('gif') ? 'gif' : 'jpg'));

return [{
  json: { ...ctx, mime, ehVideo, destino: `${ctx.slug}.${ext}` },
  binary: $input.item.binary,
}];

// SÓ grava a URL depois que o Storage confirmou o upload. Era exatamente esse
// o bug do workflow antigo da Meta: montava a URL por convenção e gravava
// mesmo quando o upload falhava — o bucket ficou com ZERO .mp4 e o banco com
// 130 storage_video_url apontando para 404.
const ctx = $('Montar destino').item.json;
const resp = $input.item.json ?? {};
const ok = resp.Key || resp.Id || resp.key || resp.id;

if (!ok) {
  return [{ json: { ad_name: ctx.ad_name, patch: { erro: 'upload sem confirmacao: ' + JSON.stringify(resp).slice(0, 200), synced_at: new Date().toISOString() } } }];
}

const publica = `https://sfxbzfaxbbdjzuhzzrjc.supabase.co/storage/v1/object/public/ad-creatives/${ctx.destino}`;
const patch = ctx.ehVideo
  ? { storage_video_url: publica, synced_at: new Date().toISOString(), erro: null }
  : { storage_url: publica, synced_at: new Date().toISOString(), erro: null };

return [{ json: { ad_name: ctx.ad_name, patch } }];

// Ramo de falha do download (arquivo removido do Drive, sem permissão, etc).
// Marca synced_at para o mesmo criativo não ser tentado a cada 20 min para
// sempre — o motivo fica na coluna erro para inspeção.
const ctx = $('Normalizar').item.json;
const msg = $input.item.json?.error?.message || $input.item.json?.message || 'falha ao baixar do Drive';
return [{
  json: {
    ad_name: ctx.ad_name,
    patch: { erro: String(msg).slice(0, 300), synced_at: new Date().toISOString() },
  },
}];
